import{_ as i,c as r,o as s,a5 as n,j as t,a as e,ba as o,bb as d,t as p,bc as m,bd as c,be as g,bf as h,bg as y,bh as b,bi as _,bj as f,bk as x,bl as u,bm as z,bn as k,bo as P,bp as D,bq as A,br as I,bs as O,bt as j,bu as M,bv as S,bw as E,bx as v,by as T,bz as w,bA as C,bB as V,bC as W,bD as L}from"./chunks/framework.BmNIwhaK.js";const F=JSON.parse('{"title":"シナリオ録画およびエディターガイド","description":"Web ブラウザ上のユーザーイベントをリアルタイムで記録し、待機条件、検証条件、リカバリスクリプトを組み合わせて安定した回帰テストシナリオを構成する方法を説明します。","frontmatter":{"title":"シナリオ録画およびエディターガイド","description":"Web ブラウザ上のユーザーイベントをリアルタイムで記録し、待機条件、検証条件、リカバリスクリプトを組み合わせて安定した回帰テストシナリオを構成する方法を説明します。","head":[["meta",{"name":"keywords","content":"SyncETA, シナリオ録画, ブラウザレコーダー, 待機レコード, 検証レコード, DOM 検証, AI 画面検証, 失敗リカバリスクリプト"}],["meta",{"property":"og:title","content":"シナリオ録画およびエディターガイド | Empasy Docs"}],["meta",{"property":"og:description","content":"Web ブラウザ上のユーザーイベントをリアルタイムで記録し、待機条件、検証条件、リカバリスクリプトを組み合わせて安定した回帰テストシナリオを構成する方法を説明します。"}],["meta",{"name":"robots","content":"index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/synceta/scenario-create"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/synceta/scenario-create"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/synceta/scenario-create"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/synceta/scenario-create"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/synceta/scenario-create"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/synceta/scenario-create"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"シナリオ録画およびエディターガイド | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Web ブラウザ上のユーザーイベントをリアルタイムで記録し、待機条件、検証条件、リカバリスクリプトを組み合わせて安定した回帰テストシナリオを構成する方法を説明します。"}],["script",{"type":"application/ld+json","data-empasy-page-jsonld":"true"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"シナリオ録画およびエディターガイド\\",\\"description\\":\\"Web ブラウザ上のユーザーイベントをリアルタイムで記録し、待機条件、検証条件、リカバリスクリプトを組み合わせて安定した回帰テストシナリオを構成する方法を説明します。\\",\\"url\\":\\"https://doc.empasy.com/ja/synceta/scenario-create\\",\\"inLanguage\\":\\"ja-JP\\",\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://doc.empasy.com/ja/synceta/scenario-create\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Empasy Inc.\\",\\"url\\":\\"https://empasy.io/\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Empasy Inc.\\",\\"url\\":\\"https://empasy.io/\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://doc.empasy.com/images/favicon.png\\"}}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Empasy Docs (JA)\\",\\"item\\":\\"https://doc.empasy.com/ja/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"シナリオ録画およびエディターガイド\\",\\"item\\":\\"https://doc.empasy.com/ja/synceta/scenario-create\\"}]}]}"]],"sort":300},"headers":[],"relativePath":"ja/synceta/scenario-create.md","filePath":"ja/synceta/scenario-create.md","lastUpdated":1795293539000}'),B={name:"ja/synceta/scenario-create.md"};function J(l,a,N,$,R,U){return s(),r("div",null,[a[7]||(a[7]=n('<h1 id="シナリオ録画およびエディターガイド" tabindex="-1">シナリオ録画およびエディターガイド <a class="header-anchor" href="#シナリオ録画およびエディターガイド" aria-label="Permalink to “シナリオ録画およびエディターガイド”">​</a></h1><p>SyncETA エディターは、ブラウザ操作（クリック、テキスト入力、ページ遷移など）をリアルタイムでキャプチャし、イベント発生時点の DOM 情報（XPath、CSS Selector、タグ属性）を構造化してテストケースを生成します。</p><hr><h2 id="_1-シナリオの定義と単位" tabindex="-1">1. シナリオの定義と単位 <a class="header-anchor" href="#_1-シナリオの定義と単位" aria-label="Permalink to “1. シナリオの定義と単位”">​</a></h2><p><strong>「シナリオ（Scenario）」</strong>は、特定のビジネスフローを完結させるテスト単位です。</p><p>例: <code>ショッピングサイトの商品検索およびカート追加</code></p><ol><li>メインホームページへアクセス</li><li>検索バーをクリックして検索キーワード（<code>ワイヤレスマウス</code>）を入力</li><li>検索を実行して結果一覧を読み込み</li><li>最初の商品をクリックして詳細ページへ移動</li><li>「カートに入れる」ボタンをクリックし、完了モーダルを検証</li></ol><hr><h2 id="_2-シナリオ作成および録画手順" tabindex="-1">2. シナリオ作成および録画手順 <a class="header-anchor" href="#_2-シナリオ作成および録画手順" aria-label="Permalink to “2. シナリオ作成および録画手順”">​</a></h2><h3 id="ステップ-1-シナリオメニューへの移動" tabindex="-1">ステップ 1: シナリオメニューへの移動 <a class="header-anchor" href="#ステップ-1-シナリオメニューへの移動" aria-label="Permalink to “ステップ 1: シナリオメニューへの移動”">​</a></h3><ol><li>左側サイドバーの <strong>「シナリオ」</strong> メニューをクリックします。</li><li>右上の <strong>「新しいシナリオ」</strong> ボタンをクリックして録画設定モーダルを開きます。</li></ol><p><img src="'+h+'" alt="シナリオ作成クリック" loading="lazy"></p><h3 id="ステップ-2-録画ブラウザおよび解像度の設定" tabindex="-1">ステップ 2: 録画ブラウザおよび解像度の設定 <a class="header-anchor" href="#ステップ-2-録画ブラウザおよび解像度の設定" aria-label="Permalink to “ステップ 2: 録画ブラウザおよび解像度の設定”">​</a></h3><ul><li><strong>対象 URL</strong>: テストを実行する Web ページのベースアドレスを入力します。</li><li><strong>録画ブラウザ</strong>: 録画を行うブラウザエンジン（Chrome、Edge など）を選択します。</li><li><strong>ビューポート解像度</strong>: 録画時に適用するブラウザ解像度を設定します（例: 1920x1080、1400x800）。</li></ul><p><img src="'+y+'" alt="シナリオ録画前の設定" loading="lazy"></p><h3 id="ステップ-3-収集イベントフィルターの設定" tabindex="-1">ステップ 3: 収集イベントフィルターの設定 <a class="header-anchor" href="#ステップ-3-収集イベントフィルターの設定" aria-label="Permalink to “ステップ 3: 収集イベントフィルターの設定”">​</a></h3><p>収集するイベントタイプ（クリック、キーボード入力、マウスオーバー、スクロールなど）を指定します。一般的な Web テストの場合は、デフォルトの推奨設定を維持します。</p><p><img src="'+b+'" alt="許可イベント設定" loading="lazy"></p><h3 id="ステップ-4-リアルタイム録画の実行" tabindex="-1">ステップ 4: リアルタイム録画の実行 <a class="header-anchor" href="#ステップ-4-リアルタイム録画の実行" aria-label="Permalink to “ステップ 4: リアルタイム録画の実行”">​</a></h3><p>録画が開始されると専用のブラウザウィンドウが表示されます。ブラウザ上で実際のユーザーフローに沿って操作を進めると、下部の一覧にイベントレコードが順次収集されます。</p><p><img src="'+_+'" alt="録画開始" loading="lazy"></p><h3 id="ステップ-5-dom-情報収集の確認" tabindex="-1">ステップ 5: DOM 情報収集の確認 <a class="header-anchor" href="#ステップ-5-dom-情報収集の確認" aria-label="Permalink to “ステップ 5: DOM 情報収集の確認”">​</a></h3><p>収集された各レコードには、イベントが発生した対象ノードのタグ、ID、Class、絶対/相対 XPath 情報が含まれます。</p><p><img src="'+f+'" alt="DOM 情報収集" loading="lazy"></p><h3 id="ステップ-6-マルチタブ操作のサポート" tabindex="-1">ステップ 6: マルチタブ操作のサポート <a class="header-anchor" href="#ステップ-6-マルチタブ操作のサポート" aria-label="Permalink to “ステップ 6: マルチタブ操作のサポート”">​</a></h3><p>録画中に新規タブまたはポップアップウィンドウが開かれた場合、タブ切り替えイベントを自動的に認識し、複数タブにまたがるシナリオを連続して録画します。</p><p><img src="'+x+'" alt="マルチタブ録画" loading="lazy"></p><hr><h2 id="_3-待機条件-wait-conditions-の追加" tabindex="-1">3. 待機条件（Wait Conditions）の追加 <a class="header-anchor" href="#_3-待機条件-wait-conditions-の追加" aria-label="Permalink to “3. 待機条件（Wait Conditions）の追加”">​</a></h2><p>非同期ネットワーク通信（AJAX/Fetch）や画面レンダリングの遅延によるテストの不安定性を防ぐため、3 種類の待機レコードをサポートしています。</p><table tabindex="0"><thead><tr><th style="text-align:left;">待機タイプ</th><th style="text-align:left;">説明</th><th style="text-align:left;">推奨される使用タイミング</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>時間待機（Fixed Timeout）</strong></td><td style="text-align:left;">指定された時間（ミリ秒）だけ一時停止します。</td><td style="text-align:left;">外部システム API の応答遅延待機</td></tr><tr><td style="text-align:left;"><strong>要素表示待機（DOM Visible）</strong></td><td style="text-align:left;">特定の DOM エレメントが画面にレンダリングされるまで待機します。</td><td style="text-align:left;">非同期レイヤーポップアップの読み込み待機</td></tr><tr><td style="text-align:left;"><strong>要素値一致待機（Value Match）</strong></td><td style="text-align:left;">対象要素のテキストまたは属性が特定の値に変化するまで待機します。</td><td style="text-align:left;">処理ステータス（「完了」）または注文番号の生成待機</td></tr></tbody></table><h3 id="時間待機条件の追加方法" tabindex="-1">時間待機条件の追加方法 <a class="header-anchor" href="#時間待機条件の追加方法" aria-label="Permalink to “時間待機条件の追加方法”">​</a></h3><ol><li>待機が必要なレコードを右クリックします。</li><li><strong>「待機条件の追加」 -&gt; 「時間待機」</strong> を選択し、待機時間（ms）を入力します。</li></ol><p><img src="'+u+'" alt="時間待機右クリック" loading="lazy"><img src="'+z+'" alt="時間待機設定" loading="lazy"><img src="'+k+'" alt="時間待機レコード作成" loading="lazy"></p><h3 id="要素表示待機条件の追加方法" tabindex="-1">要素表示待機条件の追加方法 <a class="header-anchor" href="#要素表示待機条件の追加方法" aria-label="Permalink to “要素表示待機条件の追加方法”">​</a></h3><ol><li>レコードを右クリックし、<strong>「待機条件の追加」 -&gt; 「要素表示待機」</strong> を選択します。</li><li>録画ブラウザウィンドウ上で待機対象とする DOM 要素を直接クリックして指定します。</li></ol><p><img src="'+P+'" alt="DOM 待機右クリック" loading="lazy"><img src="'+D+'" alt="DOM 要素選択" loading="lazy"><img src="'+A+'" alt="DOM 待機レコード作成" loading="lazy"></p><h3 id="要素値一致待機条件の追加方法" tabindex="-1">要素値一致待機条件の追加方法 <a class="header-anchor" href="#要素値一致待機条件の追加方法" aria-label="Permalink to “要素値一致待機条件の追加方法”">​</a></h3><ol><li>レコードを右クリックし、<strong>「待機条件の追加」 -&gt; 「要素値一致待機」</strong> を選択します。</li><li>ブラウザ上で対象要素を選択し、期待する一致テキストを入力します。</li></ol><p><img src="'+I+'" alt="値一致待機右クリック" loading="lazy"><img src="'+O+'" alt="値一致待機設定" loading="lazy"></p><hr><h2 id="_4-検証条件-assertions-の追加" tabindex="-1">4. 検証条件（Assertions）の追加 <a class="header-anchor" href="#_4-検証条件-assertions-の追加" aria-label="Permalink to “4. 検証条件（Assertions）の追加”">​</a></h2><p>テストの成否を客観的に判定するため、3 種類の検証レコードを提供しています。</p><table tabindex="0"><thead><tr><th style="text-align:left;">検証タイプ</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>要素表示検証</strong></td><td style="text-align:left;">特定の UI コンポーネント（ボタン、バナー、モーダルなど）が画面上に正しく存在するか検証</td></tr><tr><td style="text-align:left;"><strong>要素値検証</strong></td><td style="text-align:left;">特定要素のテキスト、金額、ステータス文字列が期待値と一致するか検証</td></tr><tr><td style="text-align:left;"><strong>AI 画面検証（Vision AI）</strong></td><td style="text-align:left;">ブラウザの画面キャプチャ画像に基づき、視覚的な異常の有無（レイアウト崩れ、重なり現象）を検証</td></tr></tbody></table><h3 id="要素表示および値検証の追加" tabindex="-1">要素表示および値検証の追加 <a class="header-anchor" href="#要素表示および値検証の追加" aria-label="Permalink to “要素表示および値検証の追加”">​</a></h3><p>レコードを右クリックしたうえで、<strong>「検証条件の追加」</strong> メニューから希望の検証方式を選択し、対象要素を指定します。</p><p><img src="'+j+'" alt="DOM 検証右クリック" loading="lazy"><img src="'+M+'" alt="DOM 検証対象選択" loading="lazy"><img src="'+S+'" alt="DOM 検証レコード作成" loading="lazy"></p><p><img src="'+E+'" alt="値検証右クリック" loading="lazy"><img src="'+v+'" alt="値検証設定" loading="lazy"><img src="'+T+'" alt="値検証レコード作成" loading="lazy"></p><h3 id="ai-画面検証-vision-ai" tabindex="-1">AI 画面検証（Vision AI） <a class="header-anchor" href="#ai-画面検証-vision-ai" aria-label="Permalink to “AI 画面検証（Vision AI）”">​</a></h3><p>テキストマッチングだけでは確認が難しい複合グラフィックや、レスポンシブレイアウトの正常性を検証する際に使用します。検証プロンプト（例: 「検索結果の地図領域が他の要素に覆われることなく正常に表示されているか確認」）を入力すると、実行時に画面キャプチャに基づく視覚検証を実行します。</p><p><img src="'+w+'" alt="AI 検証右クリック" loading="lazy"><img src="'+C+'" alt="AI 検証プロンプト入力" loading="lazy"></p><hr><h2 id="_5-シナリオの編集および続きからの録画" tabindex="-1">5. シナリオの編集および続きからの録画 <a class="header-anchor" href="#_5-シナリオの編集および続きからの録画" aria-label="Permalink to “5. シナリオの編集および続きからの録画”">​</a></h2><p>既存のシナリオの特定ステップ以降から、追加操作を続けて録画することができます。</p><ol><li>シナリオ一覧から対象シナリオを選択し、<strong>「編集」</strong> ボタンをクリックします。</li><li>続きの録画を開始する基準レコードを選択します。</li><li>ブラウザが起動して基準レコードまで自動再生された後、待機状態から追加のユーザー操作を記録します。</li></ol><p><img src="'+V+'" alt="シナリオ編集クリック" loading="lazy"><img src="'+W+'" alt="基準レコード選択" loading="lazy"><img src="'+L+'" alt="続きの録画実行" loading="lazy"></p><hr><h2 id="_6-付加機能" tabindex="-1">6. 付加機能 <a class="header-anchor" href="#_6-付加機能" aria-label="Permalink to “6. 付加機能”">​</a></h2>',58)),t("ul",null,[a[4]||(a[4]=t("li",null,[t("strong",null,"レコードノート（Comments）"),e(": 各ステップにテストの目的や参考事項のメモを記述します。 "),t("img",{src:o,alt:"ノート機能",loading:"lazy"})],-1)),a[5]||(a[5]=t("li",null,[t("strong",null,"失敗リカバリスクリプト（Recovery Script）"),e(": 特定ステップの失敗時にセッション終了を防ぐための例外処理 JavaScript スクリプトを指定します。 "),t("img",{src:d,alt:"リカバリスクリプト",loading:"lazy"})],-1)),t("li",null,[a[0]||(a[0]=t("strong",null,"データセット変数バインディング",-1)),a[1]||(a[1]=e(": 入力テキストをハードコーディングせず、データセット変数（",-1)),t("code",null,p(l.username),1),a[2]||(a[2]=e(" など）で置換します。 ",-1)),a[3]||(a[3]=t("img",{src:m,alt:"データセット変数",loading:"lazy"},null,-1))]),a[6]||(a[6]=t("li",null,[t("strong",null,"ステップの削除および無効化"),e(": 不要なレコードの削除、または実行対象からの一時除外を行います。 "),t("img",{src:c,alt:"ステップ削除",loading:"lazy"}),t("img",{src:g,alt:"ステップ無効化",loading:"lazy"})],-1))])])}const q=i(B,[["render",J]]);export{F as __pageData,q as default};
